import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/widgets.dart';
import 'package:logger/logger.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:wordchain/core/di/injection.dart';

/// Every sound effect. The file is `assets/audio/sfx/<name>.wav`, generated by
/// `scripts/audio/build.py` (see docs/audio.md); the enum name is the file name.
enum Sound {
  tap('tap', 0.9, voices: 2),
  toggle('toggle', 0.9),
  dialogOpen('dialog_open', 0.8),
  dialogClose('dialog_close', 0.7),
  toast('toast', 0.8),
  tab('tab', 0.8),
  // One voice per pitch step (see [KeyPitch]): the letter's pitch is the voice's
  // fixed playback rate, so no per-press rate call is needed.
  key('key', 0.7, voices: KeyPitch.steps, debounce: false),
  keyBack('key_back', 0.7, voices: 2, debounce: false),
  keySend('key_send', 0.9, debounce: false),
  accepted('accepted', 1.0),
  streak('streak', 1.0),
  rejected('rejected', 0.9),
  tileLand('tile_land', 0.8),
  oppWord('opp_word', 0.8),
  tick('tick', 0.7, voices: 2),
  timeout('timeout', 1.0),
  lifeLost('life_lost', 1.0),
  shield('shield', 0.9),
  hint('hint', 0.9),
  extraTime('extra_time', 0.9),
  longWord('long_word', 1.0),
  matchFound('match_found', 1.0),
  taunt('taunt', 0.9),
  win('win', 1.0),
  lose('lose', 1.0),
  ratingUp('rating_up', 0.9),
  ratingDown('rating_down', 0.9),
  coin('coin', 0.9),
  coinSpend('coin_spend', 0.9),
  claim('claim', 1.0),
  levelUp('level_up', 1.0);

  final String file;

  /// Mix level of this sound (0–1) before the master level.
  final double volume;

  /// Overlapping plays of the same sound allowed (fast typing, ticking).
  final int voices;

  /// Whether two plays within [AudioService._minGap] count as one. The keyboard
  /// sounds opt out: every key press is a real, separate event.
  final bool debounce;

  const Sound(this.file, this.volume, {this.voices = 1, this.debounce = true});

  String get asset => 'audio/sfx/$file.wav';
}

/// The keyboard letters' slight pitch variation: [steps] fixed playback rates,
/// one per voice of [Sound.key], so a letter always sounds the same.
abstract final class KeyPitch {
  static const steps = 7;
  static const base = 0.94;
  static const step = 0.02;

  static double rateFor(int variant) => base + (variant % steps) * step;

  static int variantFor(double rate) =>
      ((rate - base) / step).round().clamp(0, steps - 1);
}

/// Which voice of [sound]'s pool plays this time: the key sound picks the
/// voice of its pitch, every other sound rotates through its voices.
@visibleForTesting
int pickVoice(Sound sound, double rate, int counter) {
  if (sound == Sound.key) return KeyPitch.variantFor(rate);
  return counter % sound.voices;
}

/// The two seamless loops, `assets/audio/music/<name>.ogg`.
enum MusicTrack {
  menu('menu', 0.5),
  game('game', 0.4);

  final String file;
  final double volume;

  const MusicTrack(this.file, this.volume);

  String get asset => 'audio/music/$file.ogg';
}

/// What [AudioService] needs from the platform, so tests can run without a
/// native audio engine.
abstract class AudioOutput {
  Future<void> init();
  void playSfx(Sound sound, double volume, double rate);
  Future<void> playMusic(MusicTrack track, double volume);
  Future<void> pauseMusic();
  Future<void> resumeMusic();
  Future<void> stopMusic();
}

/// Sound effects and music.
///
/// Two independent switches («صدا», «موسیقی»), both on by default and stored in
/// `SharedPreferences`. The music is whatever [setMusic] last asked for; it is
/// silent while the switch is off or the app is in the background and picks up
/// again by itself. Nothing here may ever throw or block: audio is decoration,
/// so every platform failure is logged and swallowed.
class AudioService with WidgetsBindingObserver {
  static const sfxKey = 'sound_sfx_on';
  static const musicKey = 'sound_music_on';

  /// Two taps of the same sound closer than this are one (a double-fired
  /// pointer event must not double the volume).
  static const _minGap = Duration(milliseconds: 25);

  /// A sound asked for before [init] finished is played when it did, unless it
  /// is older than this (a tap sound a second late is worse than none).
  static const _earlyMaxAge = Duration(milliseconds: 400);

  final Logger _log = Logger();
  final SharedPreferences _prefs;
  final AudioOutput _out;

  final ValueNotifier<bool> sfxOn;
  final ValueNotifier<bool> musicOn;

  MusicTrack? _wanted;
  MusicTrack? _loaded;
  bool _paused = false;
  bool _foreground = true;
  bool _ready = false;
  bool _initFailed = false;
  final Map<Sound, DateTime> _last = {};
  final List<({Sound sound, double rate, DateTime at})> _early = [];

  AudioService({required SharedPreferences prefs, AudioOutput? output})
    : _prefs = prefs,
      _out = output ?? AudioPlayersOutput(),
      sfxOn = ValueNotifier(prefs.getBool(sfxKey) ?? true),
      musicOn = ValueNotifier(prefs.getBool(musicKey) ?? true);

  /// Safe to call without awaiting; never gates the first frame.
  Future<void> init() async {
    WidgetsBinding.instance.addObserver(this);
    try {
      await _out.init();
      _ready = true;
    } catch (e) {
      _initFailed = true;
      _log.w('Audio init failed, effects and music stay silent: $e');
    }
    _flushEarly();
    _syncMusic();
  }

  void play(Sound sound, {double rate = 1.0}) {
    if (!sfxOn.value || !_foreground) return;
    final now = DateTime.now();
    if (!_ready) {
      if (_initFailed) return;
      if (_early.length < 8) _early.add((sound: sound, rate: rate, at: now));
      _log.w('Sound ${sound.file} requested before audio init finished');
      return;
    }
    _fire(sound, rate, now);
  }

  void _fire(Sound sound, double rate, DateTime now) {
    if (sound.debounce) {
      final last = _last[sound];
      if (last != null && now.difference(last) < _minGap) return;
      _last[sound] = now;
    }
    try {
      _out.playSfx(sound, sound.volume, rate);
    } catch (e) {
      _log.w('Sound ${sound.file} failed: $e');
    }
  }

  void _flushEarly() {
    final now = DateTime.now();
    final early = List.of(_early);
    _early.clear();
    if (!_ready || !sfxOn.value || !_foreground) return;
    for (final e in early) {
      if (now.difference(e.at) <= _earlyMaxAge) {
        _fire(e.sound, e.rate, now);
      } else {
        _log.w('Sound ${e.sound.file} dropped: audio init took too long');
      }
    }
  }

  /// The loop that should be playing now; null = silence. Asking for the track
  /// already playing does nothing (it does not restart).
  void setMusic(MusicTrack? track) {
    _wanted = track;
    _syncMusic();
  }

  Future<void> setSfxEnabled(bool on) async {
    sfxOn.value = on;
    await _prefs.setBool(sfxKey, on);
  }

  Future<void> setMusicEnabled(bool on) async {
    musicOn.value = on;
    await _prefs.setBool(musicKey, on);
    _syncMusic();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    final fg = state == AppLifecycleState.resumed;
    if (fg == _foreground) return;
    _foreground = fg;
    _syncMusic();
  }

  /// Reconciles what the output is doing with what is wanted. A switch-off or
  /// a silent scene stops the music; going to the background only pauses it
  /// (position kept), and the same track resumes when the app returns.
  void _syncMusic() {
    if (!_ready) return;
    final want = musicOn.value ? _wanted : null;
    unawaited(_apply(want));
  }

  Future<void> _apply(MusicTrack? want) async {
    try {
      if (want == null) {
        if (_loaded != null) {
          _loaded = null;
          _paused = false;
          await _out.stopMusic();
        }
      } else if (!_foreground) {
        if (_loaded != null && !_paused) {
          _paused = true;
          await _out.pauseMusic();
        }
      } else if (want != _loaded) {
        _loaded = want;
        _paused = false;
        await _out.playMusic(want, want.volume);
      } else if (_paused) {
        _paused = false;
        await _out.resumeMusic();
      }
    } catch (e) {
      _log.w('Music failed: $e');
    }
  }

  @visibleForTesting
  MusicTrack? get playingTrack => _paused ? null : _loaded;
}

/// Fire-and-forget helper for call sites: a no-op when no [AudioService] is
/// registered (widget tests, a failed start), so a screen never has to care.
abstract final class Sfx {
  static void play(Sound sound, {double rate = 1.0}) {
    if (!getIt.isRegistered<AudioService>()) return;
    getIt<AudioService>().play(sound, rate: rate);
  }

  static void music(MusicTrack? track) {
    if (!getIt.isRegistered<AudioService>()) return;
    getIt<AudioService>().setMusic(track);
  }
}

/// One player of a sound's pool. [rate] and the volume are set once at load;
/// only `stop` + `resume` run per play, never `setSource`.
class _Voice {
  final AudioPlayer player;
  final double rate;
  bool everFired = false;
  Future<void> chain = Future.value();

  _Voice(this.player, this.rate);
}

class _Pool {
  final List<_Voice> voices;
  int counter = 0;

  _Pool(this.voices);
}

/// `audioplayers`: a pool of low-latency players per sound, one looping player
/// for the music.
///
/// Android's SoundPool player never reports that a clip ended, so its native
/// "playing" flag stays set and a second `resume()` is silently ignored. Every
/// play is therefore `stop()` (resets the flag) then `resume()` on a source that
/// was loaded once, up front. `AudioPlayer.play()` would also re-set the source
/// and the volume on every call, which is the slow part.
class AudioPlayersOutput implements AudioOutput {
  /// A play still waiting for its voice after this long is dropped: a late
  /// click is worse than a missing one.
  static const _staleAfter = Duration(milliseconds: 300);

  final Logger _log = Logger();
  // Debug-only timing lines (one short line each, see [_logTiming]).
  final Logger _timing = Logger(printer: SimplePrinter(colors: false));
  final Map<Sound, Future<_Pool>> _pools = {};
  AudioPlayer? _music;
  Timer? _fade;

  @override
  Future<void> init() async {
    // Mix with whatever the player is already listening to and never take
    // audio focus: the game must not pause a podcast, and stays silent on the
    // iOS silent switch.
    await AudioPlayer.global.setAudioContext(
      AudioContext(
        android: const AudioContextAndroid(
          contentType: AndroidContentType.sonification,
          usageType: AndroidUsageType.game,
          audioFocus: AndroidAudioFocus.none,
        ),
        iOS: AudioContextIOS(category: AVAudioSessionCategory.ambient),
      ),
    );
    // Load every effect in the background, the ones that must answer a touch
    // first. A play that arrives before its sound is loaded waits for that
    // load (the pool is a shared future) instead of being dropped.
    unawaited(_preloadAll());
  }

  static const _firstToLoad = [
    Sound.key,
    Sound.keyBack,
    Sound.keySend,
    Sound.tap,
    Sound.accepted,
    Sound.tileLand,
    Sound.rejected,
    Sound.oppWord,
    Sound.tick,
  ];

  Future<void> _preloadAll() async {
    final watch = Stopwatch()..start();
    final order = [
      ..._firstToLoad,
      for (final s in Sound.values)
        if (!_firstToLoad.contains(s)) s,
    ];
    for (final s in order) {
      try {
        await _poolFor(s);
      } catch (_) {
        // Already logged by _poolFor; a later play retries the load.
      }
    }
    if (kDebugMode) {
      _timing.i('[sfx] preloaded ${order.length} sounds in ${watch.elapsedMilliseconds} ms');
    }
  }

  /// The loaded pool of [s], loading it now if nobody did yet. A failed load is
  /// forgotten so the next play tries again.
  Future<_Pool> _poolFor(Sound s) {
    return _pools[s] ??= _load(s).catchError((Object e) {
      _pools.remove(s);
      _log.w('Loading sound ${s.file} failed: $e');
      throw e;
    });
  }

  Future<_Pool> _load(Sound s) async {
    final voices = <_Voice>[];
    for (var i = 0; i < s.voices; i++) {
      final p = AudioPlayer();
      await p.setPlayerMode(PlayerMode.lowLatency);
      await p.setReleaseMode(ReleaseMode.stop);
      await p.setVolume(s.volume);
      final rate = s == Sound.key ? KeyPitch.rateFor(i) : 1.0;
      if (rate != 1.0) await p.setPlaybackRate(rate);
      await p.setSource(AssetSource(s.asset));
      voices.add(_Voice(p, rate));
    }
    return _Pool(voices);
  }

  @override
  void playSfx(Sound sound, double volume, double rate) {
    final called = DateTime.now();
    final watch = Stopwatch()..start();
    unawaited(_trigger(sound, rate, called, watch));
  }

  Future<void> _trigger(
    Sound sound,
    double rate,
    DateTime called,
    Stopwatch watch,
  ) async {
    try {
      final pool = await _poolFor(sound);
      final poolWait = watch.elapsedMilliseconds;
      final index = pickVoice(sound, rate, pool.counter++);
      final voice = pool.voices[index];
      // One play at a time per voice, in call order: stop → resume must not
      // interleave with the next press's stop → resume.
      final run = voice.chain.then((_) async {
        if (watch.elapsed > _staleAfter) {
          _log.w('Sound ${sound.file} dropped: waited ${watch.elapsedMilliseconds} ms for its voice');
          return false;
        }
        final p = voice.player;
        if (voice.everFired) await p.stop();
        voice.everFired = true;
        await p.resume();
        return true;
      });
      voice.chain = run.then<void>((_) {}, onError: (Object _) {});
      final played = await run;
      if (kDebugMode && played) {
        _logTiming(sound, index, called, poolWait, watch.elapsedMilliseconds);
      }
    } catch (e) {
      _log.w('Sound ${sound.file} failed to play: $e');
    }
  }

  /// `[sfx] key v3 call 12:00:01.234 → started +4 ms (pool wait 0 ms)`: the time
  /// of the `Sfx.play` call and how long until the platform accepted the
  /// start. The audible start is a few ms later; compare lines, not absolutes.
  void _logTiming(Sound s, int voice, DateTime called, int poolWaitMs, int totalMs) {
    String two(int n) => n.toString().padLeft(2, '0');
    final t = '${two(called.hour)}:${two(called.minute)}:${two(called.second)}'
        '.${called.millisecond.toString().padLeft(3, '0')}';
    final slow = totalMs > 80 ? ' SLOW' : '';
    _timing.i('[sfx] ${s.file} v$voice call $t → started +$totalMs ms (pool wait $poolWaitMs ms)$slow');
  }

  Future<AudioPlayer> _musicPlayer() async {
    final existing = _music;
    if (existing != null) return existing;
    final p = AudioPlayer();
    await p.setReleaseMode(ReleaseMode.loop);
    return _music = p;
  }

  @override
  Future<void> playMusic(MusicTrack track, double volume) async {
    _fade?.cancel();
    final p = await _musicPlayer();
    await p.stop();
    await p.setVolume(0);
    await p.play(AssetSource(track.asset));
    _ramp(p, 0, volume, const Duration(milliseconds: 700));
  }

  @override
  Future<void> pauseMusic() async => _music?.pause();

  @override
  Future<void> resumeMusic() async => _music?.resume();

  @override
  Future<void> stopMusic() async {
    final p = _music;
    if (p == null) return;
    _fade?.cancel();
    _ramp(p, p.volume, 0, const Duration(milliseconds: 350), then: p.stop);
  }

  void _ramp(
    AudioPlayer p,
    double from,
    double to,
    Duration d, {
    Future<void> Function()? then,
  }) {
    const steps = 10;
    var i = 0;
    _fade = Timer.periodic(d ~/ steps, (t) {
      i++;
      p.setVolume(from + (to - from) * i / steps);
      if (i >= steps) {
        t.cancel();
        then?.call();
      }
    });
  }
}
